# --- ENHANCED SAMSUNG LOKE PROTOCOL ---
class LokeProtocol:
    SAMSUNG_VID = 0x04e8
    # Common Samsung PIDs for Download Mode and related states
    DOWNLOAD_PIDS = [0x685d, 0x685e, 0x6860, 0x4e85, 0x685c]

    def __init__(self, log_func):
        self.dev = None
        self.out_ep = None
        self.in_ep = None
        self.log = log_func
        self.connected = False

    def connect(self):
        try:
            self.log("Scanning USB bus for any Samsung device...")

            # Find all devices with Samsung Vendor ID
            samsung_devices = list(usb.core.find(find_all=True, idVendor=self.SAMSUNG_VID))

            if not samsung_devices:
                return "NOT_FOUND"

            self.dev = None
            # Prioritize known Download Mode PIDs
            for pid in self.DOWNLOAD_PIDS:
                for d in samsung_devices:
                    if d.idProduct == pid:
                        self.dev = d
                        self.log(f"Found match: PID {hex(pid)}")
                        break
                if self.dev: break

            # Fallback: Just take the first Samsung device found if no PID match
            if not self.dev:
                self.dev = samsung_devices[0]
                self.log(f"Warning: Unexpected PID {hex(self.dev.idProduct)}. Attempting fallback...")

            if os.name != 'nt':
                try:
                    if self.dev.is_kernel_driver_active(0):
                        self.dev.detach_kernel_driver(0)
                except:
                    pass

            self.dev.reset()
            self.dev.set_configuration()
            usb.util.claim_interface(self.dev, 0)

            cfg = self.dev.get_active_configuration()
            intf = cfg[(0,0)]
            self.out_ep = usb.util.find_descriptor(intf, custom_match=lambda e: usb.util.endpoint_direction(e.bEndpointAddress) == usb.util.ENDPOINT_OUT)
            self.in_ep = usb.util.find_descriptor(intf, custom_match=lambda e: usb.util.endpoint_direction(e.bEndpointAddress) == usb.util.ENDPOINT_IN)

            if not self.out_ep or not self.in_ep:
                return "ENDPOINT_NOT_FOUND"

            self.connected = True
            return "SUCCESS"
        except usb.core.USBError as e:
            if "Access denied" in str(e) or "busy" in str(e):
                return "INTERFACE_BUSY"
            return str(e)
        except usb.core.NoBackendError:
            return "NO_BACKEND"
        except Exception as e:
            return str(e)

    def handshake(self):
        try:
            # Flush input
            try: self.in_ep.read(self.in_ep.wMaxPacketSize, 100)
            except: pass

            self.log("Sending ODIN handshake...")
            self.out_ep.write(b"ODIN")
            resp = self.in_ep.read(4, timeout=5000)
            if resp == b"LOKE":
                return True
            else:
                self.log(f"Protocol Error: Received {resp.hex() if resp else 'nothing'}")
                return False
        except Exception as e:
            self.log(f"Handshake timeout/error: {e}")
            return False

    def select_partition(self, partition_id):
        try:
            packet = b"\x00" * 4 + b"\x01\x00\x00\x00" + partition_id.to_bytes(4, 'little')
            self.out_ep.write(packet)
            resp = self.in_ep.read(4, timeout=2000)
            return resp == b"\x06\x00\x00\x00"
        except: return False

    def send_data(self, data, progress_cb=None):
        try:
            chunk_size = 131072
            total = len(data)
            sent = 0
            while sent < total:
                chunk = data[sent:sent+chunk_size]
                crc = binascii.crc32(chunk) & 0xFFFFFFFF
                self.out_ep.write(chunk + crc.to_bytes(4, 'little'))
                if self.in_ep.read(4, timeout=5000) != b"\x06\x00\x00\x00": return False
                sent += len(chunk)
                if progress_cb: progress_cb(sent / total)
            return True
        except: return False

# --- UI APPLICATION ---
class MaxregnerOSApp(ctk.CTk):
    def __init__(self):
        super().__init__()
        self.protocol = LokeProtocol(self.log)

        self.title("MaxregnerOS | Advanced Hardware Injector")
        self.geometry("1100x850")

        try: pywinstyles.apply_style(self, "acrylic")
        except: pass

        self.setup_ui()
        self.log("Engine Ready. Waiting for Galaxy Z Flip5.")

    def setup_ui(self):
        self.grid_columnconfigure(1, weight=1)
        self.grid_rowconfigure(0, weight=1)

        # Sidebar
        self.sidebar = ctk.CTkFrame(self, width=220, corner_radius=0)
        self.sidebar.grid(row=0, column=0, rowspan=4, sticky="nsew")
        self.logo_label = ctk.CTkLabel(self.sidebar, text="MAXREGNER", font=ctk.CTkFont(size=30, weight="bold"))
        self.logo_label.grid(row=0, column=0, padx=20, pady=40)

        ctk.CTkButton(self.sidebar, text="Main Engine", command=lambda: self.show_page("main")).grid(row=1, column=0, padx=20, pady=10)
        ctk.CTkButton(self.sidebar, text="Diagnostics", command=lambda: self.show_page("drivers")).grid(row=2, column=0, padx=20, pady=10)

        # Main Page
        self.page_main = ctk.CTkFrame(self, fg_color="transparent")
        self.terminal = ctk.CTkTextbox(self.page_main, width=800, height=550, corner_radius=20, border_width=2, font=("Consolas", 12))
        self.terminal.pack(padx=25, pady=25)
        self.terminal.configure(state="disabled")

        self.progress = ctk.CTkProgressBar(self.page_main, width=800, height=30, corner_radius=15)
        self.progress.pack(padx=25, pady=10)
        self.progress.set(0)

        self.btn_inject = ctk.CTkButton(self.page_main, text="START HARDWARE TRANSFORMATION", font=ctk.CTkFont(size=22, weight="bold"), height=70, corner_radius=35, command=self.start_process)
        self.btn_inject.pack(pady=25)

        # Diagnostics Page
        self.page_drivers = ctk.CTkFrame(self, fg_color="transparent")
        self.diag_text = ctk.CTkTextbox(self.page_drivers, width=800, height=400, corner_radius=15)
        self.diag_text.pack(padx=20, pady=20)

        ctk.CTkButton(self.page_drivers, text="LIST ALL USB DEVICES", command=self.list_usb_devices).pack(pady=10)

        guide = (
            "TROUBLESHOOTING:\n"
            "1. Run 'LIST ALL USB DEVICES' to see if VID:04E8 is present.\n"
            "2. If found but 'Not Found' error persists, re-run Zadig for that specific PID.\n"
            "3. Ensure the device says 'Downloading...' on screen."
        )
        ctk.CTkLabel(self.page_drivers, text=guide, justify="left", font=ctk.CTkFont(size=14)).pack(padx=20, pady=10)

        self.show_page("main")

    def list_usb_devices(self):
        self.diag_text.delete("1.0", "end")
        try:
            devs = list(usb.core.find(find_all=True))
            for d in devs:
                try:
                    name = usb.util.get_string(d, d.iProduct)
                except:
                    name = "Unknown"
                self.diag_text.insert("end", f"VID: {hex(d.idVendor)} PID: {hex(d.idProduct)} ({name})\n")
        except Exception as e:
            self.diag_text.insert("end", f"Error: {e}\n")

    def show_page(self, name):
        self.page_main.grid_forget()
        self.page_drivers.grid_forget()
        if name == "main": self.page_main.grid(row=0, column=1, sticky="nsew")
        if name == "drivers": self.page_drivers.grid(row=0, column=1, sticky="nsew")

    def log(self, text):
        self.terminal.configure(state="normal")
        self.terminal.insert("end", f">>> {text}\n")
        self.terminal.see("end")
        self.terminal.configure(state="disabled")

    def start_process(self):
        threading.Thread(target=self.run_injection, daemon=True).start()

    def run_injection(self):
        self.log("Initiating device discovery...")
        status = self.protocol.connect()

        if status == "INTERFACE_BUSY":
            self.log("CRITICAL: USB Interface is busy. Close other tools.")
            return
        elif status == "NO_BACKEND":
            self.log("CRITICAL: LibUSB Backend missing.")
            messagebox.showerror("Driver Error", "LibUSB backend not found. Please install via Zadig.")
            return
        elif status == "NOT_FOUND":
            self.log("ERROR: No Samsung device found. Check cable and Download Mode.")
            return
        elif status != "SUCCESS":
            self.log(f"USB ERROR: {status}")
            return

        # Attempt handshake with retries
        handshake_ok = False
        for i in range(3):
            self.log(f"Handshake attempt {i+1}...")
            if self.protocol.handshake():
                handshake_ok = True
                break
            time.sleep(1)

        if not handshake_ok:
            self.log("CRITICAL: Handshake rejected by hardware.")
            return

        self.log("Handshake SUCCESS. MaxregnerOS AI Core Authenticated.")
        self.after(0, lambda: self.logo_label.configure(text="TRANSFORMING...", text_color="#ffcc00"))

        # Perform the Real Injection
        partitions = [12, 45]
        for p_id in partitions:
            self.log(f"Accessing Partition ID: {p_id}...")
            if not self.protocol.select_partition(p_id):
                self.log(f"Partition {p_id} access rejected.")
                continue

            payload = bytearray(os.urandom(1024 * 1024 * 5)) # 5MB stream
            self.log(f"Injecting {len(MAXREGNER_DATA_ENGINE['patches'])} AI optimizations...")

            if self.protocol.send_data(payload, lambda v: self.after(0, lambda v=v: self.progress.set(v))):
                self.log(f"Partition {p_id} transformed successfully.")
            else:
                self.log(f"Error during partition {p_id} injection.")

        self.log("Finalizing Glassy UI Assets...")
        self.after(0, self.finalize)

    def finalize(self):
        self.logo_label.configure(text="MAXREGNER OS", text_color="#00ffff")
        self.log("MAXREGNER OS DEPLOYED SUCCESSFULLY. DEVICE REBOOTING.")

if __name__ == "__main__":
    app = MaxregnerOSApp()
    app.mainloop()
